CREATE TABLE version_restore_proposals(proposal_id TEXT PRIMARY KEY REFERENCES proposals(id) ON DELETE CASCADE,target_version INTEGER NOT NULL,target_digest TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN ('restore','rollback')),requested_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL);
CREATE TRIGGER version_restore_immutable BEFORE UPDATE ON version_restore_proposals BEGIN SELECT RAISE(ABORT,'immutable_restore_lineage'); END;
CREATE TABLE source_releases(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,version INTEGER NOT NULL,source_digest TEXT NOT NULL,label TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,UNIQUE(project_id,id),FOREIGN KEY(project_id,version) REFERENCES project_versions(project_id,version));
CREATE TRIGGER source_release_digest BEFORE INSERT ON source_releases WHEN NOT EXISTS(SELECT 1 FROM project_versions v WHERE v.project_id=NEW.project_id AND v.version=NEW.version AND v.source_digest=NEW.source_digest) BEGIN SELECT RAISE(ABORT,'release_version_digest_mismatch'); END;
CREATE TRIGGER source_release_immutable BEFORE UPDATE ON source_releases BEGIN SELECT RAISE(ABORT,'immutable_source_release'); END;
CREATE TABLE deployment_version_intents(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,release_id TEXT NOT NULL,version INTEGER NOT NULL,source_digest TEXT NOT NULL,status TEXT NOT NULL CHECK(status='blocked'),reason TEXT NOT NULL CHECK(reason='hosted_deployment_not_configured'),created_by TEXT NOT NULL REFERENCES users(id),created_at INTEGER NOT NULL,FOREIGN KEY(project_id,release_id) REFERENCES source_releases(project_id,id));
CREATE TRIGGER deployment_intent_version BEFORE INSERT ON deployment_version_intents WHEN NOT EXISTS(SELECT 1 FROM source_releases r WHERE r.project_id=NEW.project_id AND r.id=NEW.release_id AND r.version=NEW.version AND r.source_digest=NEW.source_digest) BEGIN SELECT RAISE(ABORT,'deployment_version_required'); END;
CREATE TRIGGER deployment_intent_immutable BEFORE UPDATE ON deployment_version_intents BEGIN SELECT RAISE(ABORT,'immutable_deployment_intent'); END;
CREATE TRIGGER legacy_artifact_lineage_immutable BEFORE UPDATE OF project_id,job_id,digest,object_key ON artifacts BEGIN SELECT RAISE(ABORT,'immutable_artifact_lineage'); END;
CREATE TRIGGER legacy_job_version_immutable BEFORE UPDATE OF project_id,version ON jobs BEGIN SELECT RAISE(ABORT,'immutable_job_version'); END;
CREATE TRIGGER legacy_release_immutable BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT,'immutable_release'); END;
CREATE TRIGGER legacy_deployment_lineage_immutable BEFORE UPDATE OF project_id,release_id,destination ON deployments BEGIN SELECT RAISE(ABORT,'immutable_deployment_lineage'); END;
